B.blf=new A.t_("none","Nothing happens: the device gets no power.",!1,!1,!1)
B.blg=new A.t_("none","It cannot be judged: the wire functions were not verified.",!1,!1,!1)
B.blh=new A.t_("smoke","The loose connection overheats: it glows, smokes and chars the device. In a real wall this can start a fire.",!1,!1,!0)
B.bli=new A.t_("none","It does not work as it should: some part runs wrongly or not at all. That does not tell you what is wrong, so check against the diagram.",!1,!1,!1)
B.blj=new A.t_("none","It runs. There is nothing to see, and that is the danger: with no ground, a fault would energize the metal parts.",!0,!1,!1)
B.blk=new A.t_("none","It works as the diagram says.",!0,!1,!1)
B.bll=new A.t_("none","It works, and every safety rule is met.",!0,!1,!1)
B.blm=new A.t_("none","Nothing happens: it is dead. But the hot wire is connected, so it can still be live. No sparks, no smoke: that does not make it safe.",!1,!1,!1)
B.bln=new A.t_("spark","Bare copper touches something it should not: sparks. The circuit is not safe.",!1,!1,!1)
B.blo=new A.t_("none","It looks fine for now. But the support cannot carry the weight, and it can fall later.",!1,!1,!1)
B.blp=new A.t_("fire","BANG. A short circuit: a flash, sparks, smoke and a flame at the device. The breaker trips and the device is ruined. The wires and the device are not safe to use.",!1,!0,!0)
B.blq=new A.t_("arc","Hot and neutral are reversed: the parts that should be dead are live. Blue arcs show the energized metal. The simulator does not let anything run on this: it is unsafe, even if a real appliance might seem to work.",!1,!1,!1)
B.blr=new A.t_("arc","Current flows through the ground wire and the metal parts it joins. Arcs crackle at the box. This is a shock hazard.",!1,!1,!1)
B.bls=new A.t_("spark","The neutral and ground are joined: the protective device trips with a snap of sparks.",!1,!0,!1)
