B.bRU=new A.jA("Breaker off, then test","Before you touch any wire, switch its breaker OFF, then check with a voltage tester that the wire is dead. A switch on the wall is not enough.")
B.bRH=new A.jA("Lock out, tag out","On a real job you put a lock or a note on the panel so nobody switches the power back on while you work.")
B.bS0=new A.jA("Water and power","Water carries electricity. Near sinks, tubs and outdoors the outlets must be GFCI, and wet hands never touch wires.")
B.bRM=new A.jA("Eyes, ears, lungs","Safety glasses for drilling and cutting, ear protection for loud tools, and a mask when you sand drywall dust or cut tile.")
B.bS_=new A.jA("Shut the water off","Before you cut or loosen a pipe, close the main water valve and open a faucet to drain the line.")
B.d78=w([B.bRU,B.bRH,B.bS0,B.bRM,B.bS_],x.Z)
B.bSc=new A.Mj("Safety first","\ud83e\uddba",D.c7,B.d78)
B.bS1=new A.jA("Wire colours","Black is hot (it carries the power), white is neutral (the way back), bare copper or green is ground (the safety path). Red is a second hot, often used for a switched line.")
B.bS8=new A.jA("Screw colours","On an outlet the brass screw takes the hot wire, the silver screw takes the neutral and the green screw takes the ground.")
B.bRW=new A.jA("Wire size","14 gauge wire is for 15 amp circuits (lights and outlets). 12 gauge is for 20 amp circuits (kitchens). A thinner wire than the breaker allows can overheat and start a fire.")
B.bRQ=new A.jA("Breakers","A breaker is a safety switch. It trips when a circuit carries too much current, so the wires never get hot enough to burn.")
B.bS3=new A.jA("Wire nuts","Strip about 3/4 inch, twist the bare ends together clockwise, and screw on the nut until no bare copper shows. Give each wire a gentle tug.")
B.bS9=new A.jA("Switches","A switch cuts the hot wire only. The neutral goes straight through to the light.")
B.bSa=new A.jA("GFCI","A GFCI outlet watches the current going out and coming back. If a little leaks (through water or a person) it cuts the power in a fraction of a second.")
B.bRJ=new A.jA("Ceiling fans","A fan shakes and is heavy. It needs a box that says fan rated, fixed to the joist, not a plain light box.")
B.bRL=new A.jA("Heights","Outlets sit about 16 inches from the floor. Switches sit about 48 inches up, where your hand falls.")
B.d_V=w([B.bS1,B.bS8,B.bRW,B.bRQ,B.bS3,B.bS9,B.bSa,B.bRJ,B.bRL],x.Z)
B.bSf=new A.Mj("Wiring basics","\u26a1",D.cd,B.d_V)
B.bRI=new A.jA("Hot left, cold right","On a faucet, hot is on the left and cold on the right. Hot lines are marked red and cold lines blue.")
B.bRV=new A.jA("The P-trap","The curved pipe under a sink always holds a little water. That water seal stops sewer gas coming up the drain.")
B.bS5=new A.jA("Shut-off valves","Every sink and toilet has its own small valve, so you can stop the water to one fixture without turning off the whole house.")
B.bRO=new A.jA("Slip nuts","Drain joints are sealed by a washer and a slip nut. Tighten by hand and a quarter turn: too much force cracks plastic.")
B.bRN=new A.jA("Wax ring","A toilet sits on a wax ring that seals it to the floor drain. A toilet is lowered straight down once, and cannot be slid around.")
B.bS2=new A.jA("Drain slope","Drains fall about 1/4 inch per foot so water and waste keep moving. Too flat and it clogs, too steep and the water leaves the solids behind.")
B.bS7=new A.jA("Order of work","Plumbing goes from the top down on the drain (tailpiece, trap, arm) and from the wall out on the supply (valve, hose, fixture).")
B.c8L=w([B.bRI,B.bRV,B.bS5,B.bRO,B.bRN,B.bS2,B.bS7],x.Z)
B.bSd=new A.Mj("Plumbing basics","\ud83d\udeb0",D.cr,B.c8L)
B.bRK=new A.jA("Studs","Studs are the vertical 2x4 posts inside a wall, 16 inches apart from centre to centre. Everything is fixed to them.")
B.bRY=new A.jA("Drilling studs","Holes for cable go through the middle of the stud, so a nail or screw cannot reach the wire.")
B.bRP=new A.jA("Drywall","A sheet is 4 feet wide, so its edges land on studs 48 inches apart. Screws go into studs only, just under the paper.")
B.bRS=new A.jA("Taping and mud","Seams get paper tape and three thin coats of joint compound, sanded smooth between coats, then primer and paint.")
B.bS6=new A.jA("Order of a build","Frame, run the pipes and wires (rough-in), inspect, hang drywall, finish it, paint, then fit the fixtures and devices.")
B.cML=w([B.bRK,B.bRY,B.bRP,B.bRS,B.bS6],x.Z)
B.bSb=new A.Mj("Framing and walls","\ud83c\udfe0",D.dT,B.cML)
B.bRT=new A.jA("Voltage tester","A pen that glows or beeps near live wires. Test it on a known live outlet first, so you know it works.")
B.bRZ=new A.jA("Wire strippers","Strip the plastic off without nicking the copper. A nick weakens the wire.")
B.bS4=new A.jA("Adjustable wrench","For nuts on valves and hoses. Hold the fitting steady with a second wrench so you do not twist the pipe.")
B.bRX=new A.jA("Drill and screw gun","A drill makes holes through studs. A screw gun sets drywall screws to the right depth.")
B.bRR=new A.jA("Level and tape measure","Measure twice, cut once. A level makes sure outlets, shelves and pipes are straight.")
B.deH=w([B.bRT,B.bRZ,B.bS4,B.bRX,B.bRR],x.Z)
